\begin{definition}
\label{def:4.1}
Let $a\in\mathbb{R}$. A \emph{formal power series centered at $a$} is an expression of the form
\[
\label{eq:4.u1}
\sum_{n=0}^{\infty} c_n (x-a)^n,
\]
where $(c_n)_{n\ge 0}$ is a sequence of real numbers (not depending on $x$), called the \emph{coefficients}, and $x$ is an indeterminate. For each $n\ge 0$, the number $c_n$ is called the $n$th coefficient.
\end{definition}

\begin{definition}
\label{def:4.3}
[Radius of convergence]
Let $a\in\mathbb{R}$ and let $(c_n)_{n\ge 0}$ be a sequence of real numbers. Consider the power series
\[
\label{eq:4.u3}
\sum_{n=0}^{\infty} c_n (x-a)^n.
\]
Define
\[
\label{eq:4.u4}
L:=\limsup_{n\to\infty} |c_n|^{1/n}\in[0,+\infty].
\]
The \emph{radius of convergence} of the series is the number
\[
\label{eq:4.u5}
R:=\frac{1}{L},
\]
with the conventions $1/0=+\infty$ and $1/(+\infty)=0$.
\end{definition}

\begin{theorem}[Divergence outside the radius of convergence]
\label{thm:4.1.6a}
Let $\sum_{n=0}^{\infty} c_n (x-a)^n$ be a power series with radius of convergence $R\in[0,\infty]$. If $x\in\mathbb{R}$ satisfies $|x-a|>R$, then the series $\sum_{n=0}^{\infty} c_n (x-a)^n$ diverges at that value of $x$.
\end{theorem}

\begin{theorem}[Absolute convergence inside the radius of convergence]
\label{thm:4.1.6b}
Let $\sum_{n=0}^{\infty} c_n (x-a)^n$ be a power series with radius of convergence $R\in[0,\infty]$. If $x\in\mathbb{R}$ satisfies $|x-a|<R$, then the series $\sum_{n=0}^{\infty} c_n (x-a)^n$ converges absolutely at that value of $x$.
\end{theorem}

\begin{theorem}[Term-by-term integration of a power series]
\label{thm:4.1.6e}
Let $\sum_{n=0}^{\infty} c_n (x-a)^n$ be a power series with radius of convergence $R>0$, and define
\[
f(x):=\sum_{n=0}^{\infty} c_n (x-a)^n\qquad (x\in(a-R,a+R)).
\]
For any closed interval $[y,z]\subset(a-R,a+R)$, we have
\begin{equation}\label{eq:4.1.5}
\int_{y}^{z} f(x)\,dx
=\sum_{n=0}^{\infty} c_n\,\frac{(z-a)^{n+1}-(y-a)^{n+1}}{n+1}.
\end{equation}
\end{theorem}
(depend on: "Theorem 4.1.3", "Theorem 4.1.2")

\begin{definition}
\label{def:4.5}
[Real analytic functions]
Let $E\subseteq\mathbb{R}$ and let $f:E\to\mathbb{R}$. Let $a\in E$ be an interior point of $E$. The function $f$ is \emph{real analytic at $a$} if there exist $r>0$ and real coefficients $\{c_n\}_{n\ge 0}\subseteq\mathbb{R}$ such that $(a-r,a+r)\subseteq E$, the power series $\sum_{n=0}^{\infty} c_n (x-a)^n$ has radius of convergence at least $r$, and
\[
\label{eq:4.u17}
f(x)=\sum_{n=0}^{\infty} c_n (x-a)^n\qquad\text{for all }x\in(a-r,a+r).
\]
If $E$ is open and $f$ is real analytic at every $a\in E$, then $f$ is \emph{real analytic on $E$}.
\end{definition}

\begin{definition}
\label{def:4.6}
Define the function $f:\mathbb{R}\setminus\{1\}\to\mathbb{R}$ by
\[
\label{eq:4.u18}
f(x):=\frac{1}{1-x}.
\]
\end{definition}

\begin{lemma}
\label{lem:4.7}
For every $x\in(-1,1)$ we have
\[
\label{eq:4.u19}
\sum_{n=0}^{\infty} x^n = \frac{1}{1-x}=f(x).
\]
In particular, $f$ is real analytic at $0$.
\end{lemma}
(depend on: "Definition 4.1.3")

\begin{lemma}
\label{lem:4.8}
For every $x\in(1,3)$ we have
\[
\label{eq:4.u20}
\sum_{n=0}^{\infty} (-1)^{n+1}(x-2)^n = \frac{1}{1-x}=f(x).
\]
In particular, $f$ is real analytic at $2$.
\end{lemma}
(depend on: "Definition 4.1.3")

\begin{definition}
\label{def:4.7}
[$k$-times differentiability]
Let $E\subseteq\mathbb{R}$ be a set such that every point of $E$ is a limit point of $E$, and let $f:E\to\mathbb{R}$.
\begin{enumerate}
\item The function $f$ is \emph{once differentiable on $E$} if and only if $f$ is differentiable at every point of $E$, i.e., for each $x\in E$ the limit
\[
\label{eq:4.u21}
\lim_{\substack{h\to 0\\ x+h\in E}} \frac{f(x+h)-f(x)}{h}
\]
exists. In this case the \emph{first derivative} $f':E\to\mathbb{R}$ is defined by this limit.
\item For an integer $k\ge 2$, the function $f$ is \emph{$k$ times differentiable on $E$} if and only if $f$ is differentiable on $E$ and $f'$ is $(k-1)$ times differentiable on $E$.
\item If $f$ is $k$ times differentiable on $E$, define derivatives recursively by
\[
\label{eq:4.u22}
f^{(0)}:=f,\qquad f^{(1)}:=f',\qquad f^{(k)}:=(f^{(k-1)})'\ \text{for all integers }k\ge 2.
\]
\item The function $f$ is \emph{infinitely differentiable} (or \emph{smooth}) on $E$ if and only if $f$ is $k$ times differentiable on $E$ for every integer $k\ge 0$.
\end{enumerate}
\end{definition}

\begin{proposition}
\label{prop:4.2.5}
Define $f:\mathbb{R}\to\mathbb{R}$ by $f(x):=|x|^3$. Then $f$ is twice differentiable on $\mathbb{R}$, but $f$ is not three times differentiable at $0$. More precisely,
\[
f'(x)=3x|x|\quad (x\in\mathbb{R}),\qquad f''(x)=6|x|\quad (x\in\mathbb{R}),
\]
and the function $f''$ is not differentiable at $0$.
\end{proposition}

\begin{proposition}
\label{prop:4.1}
(Real analytic functions are $k$-times differentiable) Let $a\in\mathbb{R}$, let $r>0$, and let $f:(a-r,a+r)\to\mathbb{R}$ be a function such that there exist coefficients $(c_n)_{n\ge 0}$ with
\[
\label{eq:4.u23}
f(x)=\sum_{n=0}^{\infty} c_n (x-a)^n\quad\text{for all }x\in(a-r,a+r).
\]
Then for every integer $k\ge 0$, the function $f$ is $k$-times differentiable on $(a-r,a+r)$, and for all $x\in(a-r,a+r)$,
\[
\label{eq:4.u24}
f^{(k)}(x)=\sum_{n=0}^{\infty} c_{n+k}(n+1)(n+2)\cdots(n+k)(x-a)^n
=\sum_{n=0}^{\infty} c_{n+k}\frac{(n+k)!}{n!}(x-a)^n,
\]
with the convention that for $k=0$ the empty product equals $1$.
\end{proposition}

\begin{theorem}
\label{thm:4.3}
Let $E\subset\mathbb{R}$ be open, and let $f:E\to\mathbb{R}$ be real analytic on $E$, meaning that for every $a\in E$ there exist $r>0$ and coefficients $(c_n)_{n\ge 0}$ such that $(a-r,a+r)\subset E$ and
\[
\label{eq:4.u32}
f(x)=\sum_{n=0}^\infty c_n(x-a)^n\quad\text{for all }x\in(a-r,a+r),
\]
with the series converging for all $x\in(a-r,a+r)$. Then $f\in C^{\infty}(E)$. Moreover, for every integer $k\ge 0$, the derivative $f^{(k)}$ exists at every point of $E$ and is real analytic on $E$.
\end{theorem}

\begin{proposition}
\label{prop:4.2.8}
Let $f:\mathbb{R}\to\mathbb{R}$ be defined by $f(x):=|x|$. Then $f$ is not differentiable at $x=0$, and in particular $f$ is not real analytic at $0$.
Moreover, for every $a\in\mathbb{R}\setminus\{0\}$, the function $f$ is real analytic at $a$.
\end{proposition}

proof:
\begin{proof}
\emph{Non-differentiability at $0$.} For $h\neq 0$ we have
\[
\frac{f(h)-f(0)}{h}=\frac{|h|}{h}=\begin{cases}1,&h>0,\\-1,&h<0.\end{cases}
\]
The right-hand and left-hand limits as $h\to 0$ are $1$ and $-1$, respectively, so the derivative $f'(0)$ does not exist.

\emph{Not real analytic at $0$.} Real analyticity at a point implies differentiability at that point (indeed, a power series representing $f$ in a neighborhood is differentiable term-by-term). Since $f$ is not differentiable at $0$, it cannot be real analytic at $0$.

\emph{Real analyticity at $a\neq 0$.} Fix $a\in\mathbb{R}\setminus\{0\}$. Choose $r>0$ such that the open interval $(a-r,a+r)$ does not contain $0$ (for instance, take $r=|a|/2$). Then $x$ has constant sign on $(a-r,a+r)$: if $a>0$ then $x>0$ there and $f(x)=x$; if $a<0$ then $x<0$ there and $f(x)=-x$.
In either case, on $(a-r,a+r)$ the function $f$ agrees with an affine function, namely $x$ or $-x$, which is represented by a power series about $a$ (a polynomial) with positive radius of convergence. Therefore $f$ is real analytic at $a$.
\end{proof}

