\begin{theorem}
\label{thm:4.4}
[Taylor's formula]
Let $E\subseteq\mathbb{R}$, let $a$ be an interior point of $E$, and let $f:E\to\mathbb{R}$ be real analytic at $a$. Suppose there exist $r>0$ and real numbers $(c_n)_{n\ge 0}$ such that
\[
\label{eq:4.u37}
f(x)=\sum_{n=0}^{\infty} c_n (x-a)^n\quad\text{for all }x\in(a-r,a+r).
\]
Then for every integer $k\ge 0$,
\[
\label{eq:4.u38}
f^{(k)}(a)=k!\,c_k.
\]
In particular,
\[
\label{eq:4.u39}
f(x)=\sum_{n=0}^{\infty}\frac{f^{(n)}(a)}{n!}(x-a)^n\quad\text{for all }x\in(a-r,a+r).
\]
\end{theorem}

proof:
\begin{proof}
\label{prf:thm:4.4}
\begin{proof}
Fix an integer $k\ge 0$.

For each $N\ge 0$ define the polynomial
\[
\label{eq:4.u40}
S_N(x)=\sum_{n=0}^N c_n (x-a)^n.
\]
Since $f(x)=\sum_{n=0}^\infty c_n (x-a)^n$ for all $x\in(a-r,a+r)$, the sequence $(S_N)$ converges to $f$ pointwise on $(a-r,a+r)$. Moreover, for every $\rho$ with $0<\rho<r$, the power series converges uniformly on $[a-\rho,a+\rho]$, and hence $S_N\to f$ uniformly on $[a-\rho,a+\rho]$.

Differentiate term-by-term $k$ times: for $x\in(a-r,a+r)$,
\[
\label{eq:4.u41}
S_N^{(k)}(x)=\sum_{n=k}^N c_n\,n(n-1)\cdots(n-k+1)\,(x-a)^{n-k}.
\]
Fix $\rho$ with $0<\rho<r$. The differentiated series
\[
\label{eq:4.u42}
\sum_{n=k}^\infty c_n\,n(n-1)\cdots(n-k+1)\,(x-a)^{n-k}
\]
also converges uniformly on $[a-\rho,a+\rho]$, so $(S_N^{(k)})$ converges uniformly on $[a-\rho,a+\rho]$ to a function $g_k$, and standard differentiation under uniform convergence yields that $f$ is $k$ times differentiable on $(a-r,a+r)$ and
\[
\label{eq:4.u43}
f^{(k)}(x)=g_k(x)=\sum_{n=k}^\infty c_n\,n(n-1)\cdots(n-k+1)\,(x-a)^{n-k}
\quad\text{for }x\in(a-r,a+r).
\]
Evaluating at $x=a$ gives
\[
\label{eq:4.u44}
f^{(k)}(a)=\sum_{n=k}^\infty c_n\,n(n-1)\cdots(n-k+1)\,(a-a)^{n-k}=c_k\,k!.
\]
This proves $f^{(k)}(a)=k!\,c_k$.

Finally, substituting $c_n=f^{(n)}(a)/n!$ into the given power series expansion yields
\[
\label{eq:4.u45}
f(x)=\sum_{n=0}^{\infty}\frac{f^{(n)}(a)}{n!}(x-a)^n\quad\text{for all }x\in(a-r,a+r).
\]
\end{proof>
\end{proof}

