\begin{theorem}
\label{thm:4.5}
[Uniqueness of power series]
Let $E\subseteq\mathbb{R}$, let $a$ be an interior point of $E$, and let $f:E\to\mathbb{R}$. Suppose there exist sequences $(c_n)_{n\ge 0}$ and $(d_n)_{n\ge 0}$ and radii $R_c,R_d>0$ such that, for all $x\in E$ with $|x-a|<R_c$,
\[
\label{eq:4.u46}
f(x)=\sum_{n=0}^\infty c_n (x-a)^n,
\]
for all $x\in E$ with $|x-a|<R_d$,
\[
\label{eq:4.u47}
f(x)=\sum_{n=0}^\infty d_n (x-a)^n,
\]
and both series converge on their respective intervals. Then $c_n=d_n$ for all $n\ge 0$.
\end{theorem}

\begin{proposition}
\label{prop:4.2}
For every real number $x$ with $|x|<1$, the geometric series converges and satisfies
\[
\label{eq:4.u52}
\sum_{n=0}^{\infty} x^n = \frac{1}{1-x}.
\]
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:4.2}
Let $x\in\mathbb{R}$ with $|x|<1$. For $N\ge 0$, define the partial sum
\[
\label{eq:4.u53}
S_N:=\sum_{n=0}^{N} x^n.
\]
Then
\[
\label{eq:4.u54}
(1-x)S_N = S_N - xS_N = \Bigl(\sum_{n=0}^{N} x^n\Bigr) - \Bigl(\sum_{n=0}^{N} x^{n+1}\Bigr)=1-x^{N+1},
\]
so
\[
\label{eq:4.u55}
S_N=\frac{1-x^{N+1}}{1-x}.
\]
Since $|x|<1$, one has $x^{N+1}\to 0$ as $N\to\infty$. Taking limits gives
\[
\label{eq:4.u56}
\sum_{n=0}^{\infty} x^n = \lim_{N\to\infty} S_N = \lim_{N\to\infty}\frac{1-x^{N+1}}{1-x}=\frac{1}{1-x}.
\]
\end{proof}

