\begin{proposition}
\label{prop:4.3}
Let $x\in\mathbb{R}$ satisfy $\lvert x-\tfrac12\rvert<\tfrac12$. Then the geometric series $\sum_{n=0}^{\infty} 2^{n+1}\left(x-\tfrac12\right)^n$ converges and
\[
\label{eq:4.u57}
\frac{1}{1-x}=\sum_{n=0}^{\infty} 2^{n+1}\left(x-\tfrac12\right)^n.
\]
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:4.3}
Set $t=2\left(x-\tfrac12\right)$. The hypothesis $\lvert x-\tfrac12\rvert<\tfrac12$ is equivalent to $|t|<1$. Then
\[
\label{eq:4.u58}
1-x=\tfrac12-\left(x-\tfrac12\right)=\tfrac12\bigl(1-2(x-\tfrac12)\bigr)=\tfrac12(1-t),
\]
so
\[
\label{eq:4.u59}
\frac{1}{1-x}=\frac{2}{1-t}.
\]
Since $|t|<1$, the geometric series satisfies $\sum_{n=0}^{\infty} t^n=\frac{1}{1-t}$. Hence
\[
\label{eq:4.u60}
\frac{1}{1-x}=2\sum_{n=0}^{\infty} t^n=2\sum_{n=0}^{\infty}\bigl(2(x-\tfrac12)\bigr)^n=\sum_{n=0}^{\infty}2^{n+1}\left(x-\tfrac12\right)^n,
\]
which is the desired identity.
\end{proof}

