\begin{proposition}
\label{prop:4.4}
Let $n\ge 0$ be an integer and let $a,c\in\mathbb{R}$. Define $f:\mathbb{R}\to\mathbb{R}$ by $f(x)=c(x-a)^n$. Then $f$ is infinitely differentiable on $\mathbb{R}$. Moreover, for every integer $k$ with $0\le k\le n$,
\[
\label{eq:4.u61}
f^{(k)}(x)=c\,\frac{n!}{(n-k)!}(x-a)^{n-k}\qquad (x\in\mathbb{R}),
\]
and for every integer $k>n$,
\[
\label{eq:4.u62}
f^{(k)}(x)=0\qquad (x\in\mathbb{R}).
\]
\end{proposition}

\begin{proposition}
\label{prop:4.5}
Let $a,b\in\mathbb{R}$ and let $n\ge 0$ be an integer. Then for every $x\in\mathbb{R}$,
\[
\label{eq:4.u66}
(x-a)^n=\sum_{m=0}^{n} \frac{n!}{m!(n-m)!} (b-a)^{n-m}(x-b)^m.
\]
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:4.5}
Fix $x\in\mathbb{R}$. Then $x-a=(x-b)+(b-a)$, so by the binomial theorem,
\[
\label{eq:4.u67}
(x-a)^n=((x-b)+(b-a))^n=\sum_{m=0}^n \binom{n}{m}(x-b)^m(b-a)^{n-m}.
\]
Since $\binom{n}{m}=\dfrac{n!}{m!(n-m)!}$, this equals
\[
\label{eq:4.u68}
\sum_{m=0}^{n} \frac{n!}{m!(n-m)!} (b-a)^{n-m}(x-b)^m,
\]
which is the desired identity.
\end{proof}

