\begin{proposition}
\label{prop:4.6}
Let $r>0$ and let $x\in\mathbb{R}$ satisfy $|x|<r$. Then
\[
\label{eq:4.u69}
\frac{r}{r-x}=\sum_{n=0}^{\infty} x^n r^{-n}.
\]
\end{proposition}

\begin{proposition}
\label{prop:4.7}
Let $r>0$, let $m\ge 0$ be an integer, and let $x\in\mathbb{R}$ satisfy $|x|<r$. Then
\[
\label{eq:4.u75}
\frac{r}{(r-x)^{m+1}}=\sum_{n=m}^{\infty} \frac{n!}{m!(n-m)!} x^{n-m} r^{-n}.
\]
Moreover, the series on the right-hand side converges absolutely for every $x\in(-r,r)$.
\end{proposition}

\begin{proposition}
\label{prop:4.2.8.a}
Let $E\subseteq\mathbb{R}$ and let $a$ be an interior point of $E$. Let $f:E\to\mathbb{R}$ be real analytic at $a$, and suppose $f$ has a power series expansion
\begin{equation}\label{eq:4.2.4}
 f(x)=\sum_{n=0}^{\infty} c_n (x-a)^n
\end{equation}
which converges (at least) for all $x\in(a-r,a+r)$ for some $r>0$.
Let $(b-s,b+s)$ be any open interval with $s>0$ such that $(b-s,b+s)\subseteq(a-r,a+r)$.
Then $|a-b|\le r-s$; in particular $|a-b|<r$.
\end{proposition}

\begin{proposition}
\label{prop:4.2.8.b}
Assume the hypotheses and notation of Proposition~\ref{prop:4.2.8.a}. Then for every $\epsilon$ with $0<\epsilon<r$, there exists a constant $C>0$ such that
\[
|c_n|\le C\,(r-\epsilon)^{-n}\quad\text{for all integers }n\ge 0.
\]
\end{proposition}
(depend on: "Proposition 4.2.10")

\begin{proposition}
\label{prop:4.2.8.c}
Assume the hypotheses and notation of Proposition~\ref{prop:4.2.8.a}, and let $(b-s,b+s)\subseteq(a-r,a+r)$ with $s>0$.
For each integer $m\ge 0$, define
\begin{equation}\label{eq:4.2.7}
 d_m:=\sum_{n=m}^{\infty} \frac{n!}{m!(n-m)!}(b-a)^{n-m}c_n.
\end{equation}
Then for every $m\ge0$ the series defining $d_m$ is absolutely convergent; hence each $d_m$ is well-defined.
\end{proposition}
(depend on: "Proposition 4.2.10", "Proposition 4.2.11")

\begin{proposition}
\label{prop:4.2.8.d}
Assume the hypotheses and notation of Proposition~\ref{prop:4.2.8.c}. Then for every $\epsilon$ with $0<\epsilon<s$, there exists a constant $C>0$ such that
\begin{equation}\label{eq:4.2.8}
|d_m|\le C\,(s-\epsilon)^{-m}\quad\text{for all integers }m\ge 0.
\end{equation}
\end{proposition}
(depend on: "Proposition 4.2.12", "Proposition 4.2.10", "Proposition 4.2.11")

\begin{proposition}
\label{prop:4.2.8.f}
Assume the hypotheses and notation of Proposition~\ref{prop:4.2.8.a}. Then $f$ is real analytic at every point $b\in(a-r,a+r)$.
\end{proposition}
(depend on: "Proposition 4.2.10", "Proposition 4.2.14", "Proposition 4.2.12", "Proposition 4.2.11", "Proposition 4.2.13")

proof:
\begin{proof}
Fix any $b\in(a-r,a+r)$. Choose $s>0$ such that $(b-s,b+s)\subseteq(a-r,a+r)$.
By Proposition~\ref{prop:4.2.8.e}, there exists a power series $\sum_{m=0}^\infty d_m(x-b)^m$ with positive radius of convergence (at least $s$) that converges to $f(x)$ for all $x\in(b-s,b+s)$.
This is exactly the definition of $f$ being real analytic at $b$.
\end{proof}

