\begin{lemma}
\label{lem:4.1}
[Summation by parts formula]
Let $(a_n)_{n\ge 0}$ and $(b_n)_{n\ge 0}$ be sequences of real numbers with $\lim_{n\to\infty} a_n = A$ and $\lim_{n\to\infty} b_n = B$. Assume that the series $\sum_{n=0}^{\infty} (a_{n+1}-a_n)b_n$ converges. Then the series $\sum_{n=0}^{\infty} a_{n+1}(b_{n+1}-b_n)$ converges and
\[
\label{eq:4.u109}
\sum_{n=0}^{\infty} (a_{n+1}-a_n)b_n \,=\, AB - a_0 b_0 - \sum_{n=0}^{\infty} a_{n+1}(b_{n+1}-b_n).
\]
\end{lemma}

\begin{thm}\label{thm:4.3.1}
[Abel's theorem]
Let $f(x)=\sum_{n=0}^{\infty} c_n (x-a)^n$ be a real power series centered at $a$ with radius of convergence $0<R<\infty$.

(1) If the series converges at $x=a+R$, i.e. if $\sum_{n=0}^{\infty} c_n R^n$ converges, then $f$ is continuous at $a+R$ from within the interval $(a-R,a+R)$, i.e.
\begin{equation}\label{eq:4.3.2}
\lim_{x\to a+R\, :\, x\in(a-R,a+R)} \sum_{n=0}^{\infty} c_n (x-a)^n 
= \sum_{n=0}^{\infty} c_n R^n.
\end{equation}

(2) Similarly, if the series converges at $x=a-R$, i.e. if $\sum_{n=0}^{\infty} c_n (-R)^n$ converges, then $f$ is continuous at $a-R$ from within $(a-R,a+R)$, i.e.
\begin{equation}\label{eq:4.3.1}
\lim_{x\to a-R\, :\, x\in(a-R,a+R)} \sum_{n=0}^{\infty} c_n (x-a)^n 
= \sum_{n=0}^{\infty} c_n (-R)^n.
\end{equation}
\end{thm}

\begin{theorem}
\label{thm:4.9}
Let $a\in\mathbb{R}$ and $r>0$. Let $f,g:(a-r,a+r)\to\mathbb{R}$ be analytic, and suppose that for all $x\in(a-r,a+r)$,
\[
\label{eq:4.u132}
f(x)=\sum_{n=0}^{\infty} c_n (x-a)^n,\qquad g(x)=\sum_{n=0}^{\infty} d_n (x-a)^n,
\]
where each series converges to the corresponding function on $(a-r,a+r)$. Define, for $n\ge 0$,
\[
\label{eq:4.u133}
e_n:=\sum_{m=0}^{n} c_m d_{n-m}.
\]
Then the product $fg:(a-r,a+r)\to\mathbb{R}$ is analytic on $(a-r,a+r)$ and, for all $x\in(a-r,a+r)$,
\[
\label{eq:4.u134}
f(x)g(x)=\sum_{n=0}^{\infty} e_n (x-a)^n.
\]
\end{theorem}

\begin{definition}
\label{def:4.8}
[Exponential function]
For every real number $x\in\mathbb{R}$, the \emph{exponential function} is defined by the power series
\[
\label{eq:4.u142}
\exp(x) := \sum_{n=0}^{\infty} \frac{x^n}{n!}.
\]
\end{definition}

\begin{thm}[Basic properties of $\exp$, part (a)]\label{thm:4.5.2a}
For every real number $x$, the series
\[
\sum_{n=0}^{\infty} \frac{x^n}{n!}
\]
is absolutely convergent. In particular, the function $\exp:\mathbb{R}\to\mathbb{R}$ defined by
\[
\exp(x):=\sum_{n=0}^{\infty} \frac{x^n}{n!}
\]
exists for every $x\in\mathbb{R}$, the above power series has infinite radius of convergence, and $\exp$ is real analytic on $\mathbb{R}$.
\end{thm}

\begin{thm}[Basic properties of $\exp$, part (b)]\label{thm:4.5.2b}
The function $\exp:\mathbb{R}\to\mathbb{R}$ is differentiable on $\mathbb{R}$, and for every $x\in\mathbb{R}$ we have
\[
\exp'(x)=\exp(x).
\]
\end{thm}

\begin{thm}[Basic properties of $\exp$, part (c)]\label{thm:4.5.2c}
The function $\exp$ is continuous on $\mathbb{R}$. Moreover, for every $a,b\in\mathbb{R}$,
\[
\int_{[a,b]} \exp(x)\,dx = \exp(b)-\exp(a).
\]
\end{thm}

\begin{thm}[Basic properties of $\exp$, part (d)]\label{thm:4.5.2d}
For all $x,y\in\mathbb{R}$, one has
\[
\exp(x+y)=\exp(x)\exp(y).
\]
\end{thm}

\begin{thm}[Basic properties of $\exp$, part (e)]\label{thm:4.5.2e}
We have $\exp(0)=1$. Moreover, for every $x\in\mathbb{R}$, $\exp(x)>0$ and
\[
\exp(-x)=\frac{1}{\exp(x)}.
\]
\end{thm}

\begin{thm}[Basic properties of $\exp$, part (f)]\label{thm:4.5.2f}
The function $\exp$ is strictly increasing on $\mathbb{R}$. Equivalently, for all $x,y\in\mathbb{R}$,
\[
y>x \iff \exp(y)>\exp(x).
\]
\end{thm}

proof:
\begin{proof}
By part (b), $\exp$ is differentiable on $\mathbb{R}$ and $\exp'(x)=\exp(x)$. By part (e), $\exp(x)>0$ for all $x$, hence $\exp'(x)>0$ for all $x$. Therefore $\exp$ is strictly increasing on $\mathbb{R}$.

In particular, if $y>x$, then strict monotonicity gives $\exp(y)>\exp(x)$. Conversely, if $\exp(y)>\exp(x)$ and $y\le x$, then monotonicity would imply $\exp(y)\le\exp(x)$, a contradiction. Hence $y>x$.
\end{proof}

