\begin{definition}
\label{def:4.9}
[Euler's number]
Euler's number $e$ is the real number defined by the convergent series
\[
\label{eq:4.u152}
e := \exp(1) := \sum_{n=0}^{\infty} \frac{1}{n!}.
\]
\end{definition}

\begin{proposition}
\label{prop:4.9}
For every real number $x$, the exponential function satisfies
\[
\label{eq:4.u153}
\exp(x)=e^x.
\]
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:4.9}
Define $f:\mathbb{R}\to(0,\infty)$ by $f(x)=e^x$, and define $g:\mathbb{R}\to(0,\infty)$ by $g(x)=\exp(x)$. By the defining properties of the exponential function, both $f$ and $g$ satisfy
\[
\label{eq:4.u154}
h(0)=1,\qquad h(x+y)=h(x)h(y)\quad\text{for all }x,y\in\mathbb{R},\qquad h'(0)=1.
\]
Let $q\in\mathbb{Q}$. Writing $q=m/n$ with $m\in\mathbb{Z}$ and $n\in\mathbb{N}$, the functional equation implies $h(m)=h(1)^m$ for integers $m$, and $h(1)=h(1/n)^n$, hence $h(1/n)=h(1)^{1/n}$ and therefore $h(m/n)=h(1)^{m/n}$. Since $f(1)=e$ and $g(1)=e$ (by definition of the constant $e$ as the value of the exponential at $1$), it follows that $f(q)=g(q)=e^q$ for all $q\in\mathbb{Q}$.
Both $f$ and $g$ are differentiable on $\mathbb{R}$, hence continuous. For any real $x$, choose a sequence $(q_k)\subset\mathbb{Q}$ with $q_k\to x$. Then
\[
\label{eq:4.u155}
f(x)=\lim_{k\to\infty} f(q_k)=\lim_{k\to\infty} e^{q_k}=\lim_{k\to\infty} g(q_k)=g(x),
\]
so $\exp(x)=e^x$ for all $x\in\mathbb{R}$.
\end{proof}

