\begin{definition}
\label{def:4.10}
[Natural logarithm]
The natural logarithm is the function $\log:(0,\infty)\to\mathbb{R}$ (also denoted $\ln$) defined as the inverse of the exponential function $\exp:\mathbb{R}\to(0,\infty)$. Thus, for every $x>0$ and every $y\in\mathbb{R}$,
\[
\label{eq:4.u156}
\exp(\log(x))=x,\qquad \log(\exp(y))=y.
\]
\end{definition}

\begin{thm}[Logarithm properties, part (b)]\label{thm:4.5.6b}
For all $x,y\in(0,\infty)$, one has
\[
\ln(xy)=\ln(x)+\ln(y).
\]
\end{thm}

\begin{thm}[Logarithm properties, part (c)]\label{thm:4.5.6c}
We have $\ln(1)=0$. Moreover, for every $x\in(0,\infty)$,
\[
\ln(1/x)=-\ln(x).
\]
\end{thm}

proof:
\begin{proof}
Fix $x>0$ and $y\in\mathbb{R}$. By definition, $x^y:=\exp(y\ln x)$. Apply $\ln$ to both sides and use that $\ln$ is the inverse of $\exp$:
\[
\ln(x^y)=\ln(\exp(y\ln x))=y\ln x.
\]
\end{proof}

