\begin{thm}[Logarithm properties, part (e)]\label{thm:4.5.6e}
For any $x\in(-1,1)$, we have
\[
\label{eq:4.5.6}
\ln(1-x)=-\sum_{n=1}^{\infty}\frac{x^n}{n}.
\]
In particular, $\ln$ is real analytic at $1$, with the power series expansion
\[
\label{eq:4.5.7}
\ln(x)=\sum_{n=1}^{\infty}\frac{(-1)^{n+1}}{n}(x-1)^n
\]
for $x\in(0,2)$, with radius of convergence $1$.
\end{thm}

