\begin{proposition}
\label{prop:4.13}
Define $f:\mathbb{R}\to\mathbb{R}$ by
\[
\label{eq:4.u196}
f(x)=
\begin{cases}
\exp(-1/x),& x>0,\\
0,& x\le 0.
\end{cases}
\]
Then $f\in C^{\infty}(\mathbb{R})$, and for every integer $k\ge 0$ one has $f^{(k)}(0)=0$. Moreover, $f$ is not real analytic at $0$.
\end{proposition}

\begin{theorem}
\label{thm:4.13}
The natural logarithm function $\ln:(0,+\infty)\to\mathbb{R}$ is real analytic on $(0,+\infty)$.
\end{theorem}

proof:
\begin{proof}
\label{prf:thm:4.13}
Fix $a\in(0,+\infty)$. Define
\[
\label{eq:4.u200}
f(x)=\ln x-\ln a=\ln\Bigl(1+\frac{x-a}{a}\Bigr),\qquad x>0.
\]
For $|u|<1$, the power series
\[
\label{eq:4.u201}
\sum_{n=1}^\infty (-1)^{n+1}\frac{u^n}{n}
\]
converges absolutely and uniformly on $[-r,r]$ for every $0<r<1$, hence defines a real analytic function there. For $|u|<1$, its termwise derivative is
\[
\label{eq:4.u202}
\sum_{n=1}^\infty (-1)^{n+1}u^{n-1}=\frac{1}{1+u},
\]
so the series differs from $\ln(1+u)$ by a constant; evaluating at $u=0$ gives that constant as $0$. Therefore
\[
\label{eq:4.u203}
\ln(1+u)=\sum_{n=1}^\infty (-1)^{n+1}\frac{u^n}{n}\qquad (|u|<1).
\]
Set $u=(x-a)/a$. Then $|u|<1$ is equivalent to $|x-a|<a$, and for such $x$,
\[
\label{eq:4.u204}
\ln x=\ln a+\sum_{n=1}^\infty (-1)^{n+1}\frac{1}{n}\Bigl(\frac{x-a}{a}\Bigr)^n.
\]
Thus $\ln x$ admits a convergent power series expansion in a neighborhood of $a$. Since $a\in(0,+\infty)$ is arbitrary, $\ln$ is real analytic on $(0,+\infty)$.
\end{proof}

