\begin{proposition}
\label{prop:4.14}
Let $f:\mathbb{R}\to(0,\infty)$ be real analytic and satisfy $f'(x)=f(x)$ for all $x\in\mathbb{R}$. Then there exists a constant $C>0$ such that $f(x)=Ce^x$ for all $x\in\mathbb{R}$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:4.14}
Define $g:\mathbb{R}\to\mathbb{R}$ by $g(x)=e^{-x}f(x)$. Since $f$ is real analytic and $x\mapsto e^{-x}$ is real analytic, the function $g$ is real analytic. Differentiate:
\[
\label{eq:4.u205}
g'(x)=(-e^{-x})f(x)+e^{-x}f'(x)=e^{-x}(f'(x)-f(x))=0
\]
for all $x\in\mathbb{R}$. Hence $g$ is constant on $\mathbb{R}$, so there exists $C\in\mathbb{R}$ with $g(x)=C$ for all $x$. Therefore $f(x)=Ce^x$ for all $x\in\mathbb{R}$. Since $f(x)>0$ for all $x$, it follows that $C=g(0)=f(0)>0$.
\end{proof}

