\begin{proposition}
\label{prop:4.15}
Let $m\in\mathbb{N}$ with $m\ge 1$. Then
\[
\label{eq:4.u206}
\lim_{x\to+\infty}\frac{e^x}{x^m}=+\infty.
\]
\end{proposition}

\begin{proposition}
\label{prop:4.16}
Let $P(x)$ be a real polynomial and let $c>0$. Then there exists $N\in\mathbb{R}$ such that for all real $x>N$ one has
\[
\label{eq:4.u211}
e^{cx} > |P(x)|.
\]
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:4.16}
If $P\equiv 0$, then $|P(x)|=0<e^{cx}$ for all $x$, so any $N$ works. Assume $P\not\equiv 0$ and write $P(x)=\sum_{k=0}^m a_k x^k$ with $a_m\neq 0$.

For each integer $k\ge 0$, the limit $\lim_{x\to\infty} x^k e^{-cx}=0$ holds. Indeed, for $k=0$ this is $e^{-cx}\to 0$. If $\lim_{x\to\infty} x^k e^{-cx}=0$, then by L'H\^opital's rule,
\[
\label{eq:4.u212}
\lim_{x\to\infty} x^{k+1} e^{-cx} = \lim_{x\to\infty} \frac{x^{k+1}}{e^{cx}} = \lim_{x\to\infty} \frac{(k+1)x^k}{c e^{cx}} = \frac{k+1}{c}\lim_{x\to\infty} x^k e^{-cx}=0,
\]
so the statement follows for all $k$ by induction.

For each $k=0,\dots,m$, choose $N_k$ such that $|a_k|x^k e^{-cx} < \frac{1}{m+1}$ for all $x>N_k$. Let $N=\max\{N_0,\dots,N_m\}$. Then for all $x>N$,
\[
\label{eq:4.u213}
|P(x)|e^{-cx} \le \sum_{k=0}^m |a_k|x^k e^{-cx} < \sum_{k=0}^m \frac{1}{m+1} = 1.
\]
Multiplying by $e^{cx}>0$ yields $|P(x)|<e^{cx}$ for all $x>N$.
\end{proof}

