\begin{definition}
\label{def:4.11}
[Complex numbers]
The set of \emph{complex numbers} is
\[
\label{eq:4.u214}
\mathbb{C}=\{\,a+bi\mid a,b\in\mathbb{R}\,\},
\]
where $i$ is a symbol satisfying $i^2=-1$.
\end{definition}

\begin{definition}
\label{def:4.12}
[Complex numbers]\begin{enumerate}\item A \emph{complex number} is an ordered pair $(a,b)$ with $a,b\in\mathbb{R}$.\item Two complex numbers $(a,b)$ and $(c,d)$ are \emph{equal} if and only if $a=c$ and $b=d$.\item The set of all complex numbers is denoted by $\mathbb{C}$ and is defined by $\mathbb{C}=\mathbb{R}\times\mathbb{R}$.\end{enumerate}\end{definition}

\begin{definition}
\label{def:4.14}
[Complex addition, negation, and zero]
Let $\mathbb{C}$ denote the set of ordered pairs of real numbers. For $z=(a,b)\in\mathbb{C}$ and $w=(c,d)\in\mathbb{C}$, define the \emph{sum} $z+w\in\mathbb{C}$ by
\[
\label{eq:4.u217}
z+w := (a+c,\, b+d).
\]
Define the \emph{additive inverse} (negation) of $z$ by
\[
\label{eq:4.u218}
-z := (-a,\,-b).
\]
Define the \emph{complex zero} (additive identity) by
\[
\label{eq:4.u219}
0_C := (0,0).
\]
\end{definition}

 egin{lemma}
\label{lem:4.2}
[Addition on $\mathbb{C}$ satisfies the abelian group axioms]
For all $z_1,z_2,z_3\in\mathbb{C}$ the following identities hold:
 egin{enumerate}
\item (Commutativity) $z_1+z_2=z_2+z_1$.
\item (Associativity) $(z_1+z_2)+z_3=z_1+(z_2+z_3)$.
\item (Additive identity) $z_1+0_C=0_C+z_1=z_1$.
\item (Additive inverse) $z_1+(-z_1)=(-z_1)+z_1=0_C$.
\end{enumerate}
In particular, $(\mathbb{C},+)$ is an abelian group with identity element $0_C$.
\end{lemma}

\begin{definition}
\label{def:4.16}
[Complex multiplication]
A \emph{complex number} is an ordered pair of real numbers. For complex numbers $z=(a,b)$ and $w=(c,d)$, the \emph{product} $zw$ is defined by
\[
\label{eq:4.u228}
zw := (ac-bd,\,ad+bc).
\]
The \emph{complex multiplicative identity} is the complex number
\[
\label{eq:4.u229}
1_C := (1,0).
\]
\end{definition}

\begin{lemma}\label{lem:4.3.comm}
For all $z_1,z_2\in\mathbb{C}$, we have
\[
\label{eq:4.u230}
z_1 z_2 = z_2 z_1.
\]
\end{lemma}

proof:
\begin{proof}
This is a basic field property of $\mathbb{C}$: multiplication on $\mathbb{C}$ is commutative.
\end{proof}

content:
