\begin{definition}
\label{def:4.17}
[Embedding of real numbers into complex numbers]
Define the map \(\iota:\mathbb{R}\to\mathbb{C}\) by \(\iota(x):=(x,0)\). Under the identification \(x\equiv (x,0)\), equality and the operations of addition, negation, and multiplication on \(\mathbb{R}\) agree with the corresponding operations induced from \(\mathbb{C}\); namely, for all \(x,y,x_1,x_2\in\mathbb{R}\),
\[
\label{eq:4.u242}
x=y\iff (x,0)=(y,0),\qquad (x_1+x_2,0)=(x_1,0)+(x_2,0),\qquad (-x,0)=-(x,0),\qquad (x_1x_2,0)=(x_1,0)(x_2,0).
\]
\end{definition}

\begin{definition}
\label{def:4.18}
[Imaginary unit]
The \emph{imaginary unit} is the complex number \(i\in\mathbb{C}\) defined by \(i:=(0,1)\).
\end{definition}

\begin{lemma}
\label{lem:4.4}
Every complex number $z\in\mathbb{C}$ can be written uniquely in the form $z=a+bi$ for some $a,b\in\mathbb{R}$. Moreover, $i^2=-1$ and $-z=(-1)z$.
\end{lemma}

\begin{definition}
\label{def:4.19}
[Real and imaginary parts; complex conjugate]
Let $z\in\mathbb{C}$. If $z=a+bi$ for some $a,b\in\mathbb{R}$, define the \emph{real part} and \emph{imaginary part} of $z$ by
\[
\label{eq:4.u246}
\Re(z):=a,\qquad \Im(z):=b.
\]
Then $z=\Re(z)+i\Im(z)$. The number $z$ is called \emph{real} if $\Im(z)=0$, and $z$ is called \emph{imaginary} (i.e. purely imaginary) if $\Re(z)=0$.
The \emph{complex conjugate} of $z$ is defined by
\[
\label{eq:4.u247}
\overline z:=\Re(z)-i\Im(z).
\]
\end{definition}

\begin{lemma}
\label{lem:4.5}
[Complex conjugation is an involution]
Let $z,w\in\mathbb{C}$. Then
\[
\label{eq:4.u248}
\overline{z+w}=\bar z+\bar w,\qquad \overline{-z}=-\bar z,\qquad \overline{zw}=\bar z\,\bar w,
\qquad \overline{\bar z}=z.
\]
Moreover, $\bar z=\bar w$ if and only if $z=w$, and $\bar z=z$ if and only if $z\in\mathbb{R}$.
\end{lemma}

\begin{definition}
\label{def:4.20}
[Complex absolute value]
For a complex number $z\in\mathbb{C}$ written as $z=a+bi$ with $a,b\in\mathbb{R}$, the (complex) absolute value of $z$ is the nonnegative real number
\[
\label{eq:4.u255}
|z|:=\sqrt{a^{2}+b^{2}}=(a^{2}+b^{2})^{1/2}.
\]
\end{definition}

\begin{lemma}\label{lem:4.6.11.nonneg}
For every $z\in\mathbb{C}$, the complex absolute value $|z|$ is a non-negative real number.
\end{lemma}

proof:
\begin{proof}
By definition, $|z| := \sqrt{z\overline z}$. Since $z\overline z\in\mathbb{R}$ and $z\overline z\ge 0$, its square root is a real number and is non-negative.
\end{proof}

content:
\begin{lemma}\label{lem:4.6.11.zero_iff}
For every $z\in\mathbb{C}$, we have $|z|=0$ if and only if $z=0$.
\end{lemma}

proof:
\begin{proof}
Using $|z|=\sqrt{z\overline z}$, we have $|z|=0\iff z\overline z=0$. But $z\overline z=0$ holds if and only if $z=0$ (e.g. writing $z=a+bi$ gives $z\overline z=a^2+b^2$, which is $0$ iff $a=b=0$).
\end{proof}

\begin{proof}
This is immediate from the definition $|z|:=\sqrt{z\overline z}$. Squaring both sides gives $|z|^2=z\overline z$, and conversely taking square roots (noting $z\overline z\ge 0$) gives $|z|=\sqrt{z\overline z}$.
\end{proof}

content:
\begin{lemma}\label{lem:4.6.11.mul}
For all $z,w\in\mathbb{C}$, we have
\[
|zw|=|z|\,|w|.
\]
\end{lemma}

\begin{lemma}\label{lem:4.6.11.conj}
For every $z\in\mathbb{C}$, we have
\[
|\overline z|=|z|.
\]
\end{lemma}

proof:
\begin{proof}
We have $|\overline z|^2=\overline z\,\overline{\overline z}=\overline z\,z=z\overline z=|z|^2$. Both $|\overline z|$ and $|z|$ are non-negative real numbers, so taking square roots yields $|\overline z|=|z|$.
\end{proof}

