\begin{lemma}\label{lem:4.6.11.re_bound}
For every $z\in\mathbb{C}$, we have
\[
-|z|\le \Re(z)\le |z|.
\]
\end{lemma}

proof:
\begin{proof}
Write $z=a+bi$ with $a=\Re(z)$ and $b=\Im(z)$. Then $|z|=\sqrt{a^2+b^2}$. Since $a^2\le a^2+b^2$, we get $|a|\le \sqrt{a^2+b^2}=|z|$, i.e. $-|z|\le a\le |z|$.
\end{proof}

content:
\begin{lemma}\label{lem:4.6.11.im_bound}
For every $z\in\mathbb{C}$, we have
\[
-|z|\le \Im(z)\le |z|.
\]
\end{lemma}

proof:
\begin{proof}
Write $z=a+bi$ with $b=\Im(z)$. Then $|z|=\sqrt{a^2+b^2}$ and $b^2\le a^2+b^2$, hence $|b|\le |z|$, i.e. $-|z|\le \Im(z)\le |z|$.
\end{proof}

content:
\begin{lemma}\label{lem:4.6.11.reim_sum_bound}
For every $z\in\mathbb{C}$, we have
\[
|z|\le |\Re(z)|+|\Im(z)|.
\]
\end{lemma}

\begin{definition}
\label{def:4.21}
[Complex reciprocal and quotient]
Let $z\in\mathbb{C}$. If $z\neq 0$, the (multiplicative) reciprocal of $z$ is the complex number
\[
\label{eq:4.u267}
z^{-1}:=|z|^{-2}\,\overline{z}.
\]
The reciprocal of $0$ is undefined.

Let $z,w\in\mathbb{C}$ with $w\neq 0$. The quotient $z/w$ is defined by
\[
\label{eq:4.u268}
\frac{z}{w}:=z\,w^{-1}.
\]
\end{definition}

\begin{lemma}
\label{lem:4.7}
Let $d:\mathbf{C}\times\mathbf{C}\to[0,\infty)$ be defined by
\[
\label{eq:4.u269}
d(z,w)=|z-w|,\qquad z,w\in\mathbf{C},
\]
where $|\cdot|$ denotes the complex modulus. Then $(\mathbf{C},d)$ is a metric space. Moreover, for any sequence $(z_n)_{n=1}^\infty\subset\mathbf{C}$ and any $z\in\mathbf{C}$,
\[
\label{eq:4.u270}
\lim_{n\to\infty} z_n=z \text{ in } (\mathbf{C},d)
\]
if and only if
\[
\label{eq:4.u271}
\lim_{n\to\infty}\Re(z_n)=\Re(z)\quad\text{and}\quad \lim_{n\to\infty}\Im(z_n)=\Im(z).
\]
\end{lemma}

\begin{lemma}
\label{lem:4.8}
[Complex limit laws]
Let $(z_n)_{n=1}^\infty$ and $(w_n)_{n=1}^\infty$ be sequences in $\mathbb{C}$ with
\[
\label{eq:4.u277}
\lim_{n\to\infty} z_n = z\in\mathbb{C},\qquad \lim_{n\to\infty} w_n = w\in\mathbb{C},
\]
and let $c\in\mathbb{C}$. Then the sequences $(z_n+w_n)_{n=1}^\infty$, $(z_n-w_n)_{n=1}^\infty$, $(c z_n)_{n=1}^\infty$, $(z_n w_n)_{n=1}^\infty$, and $(\overline{z_n})_{n=1}^\infty$ are convergent, and
\begin{align}
\label{eq:4.u276}
\lim_{n\to\infty}(z_n+w_n) &= z+w,\\
\lim_{n\to\infty}(z_n-w_n) &= z-w,\\
\lim_{n\to\infty}(c z_n) &= c z,\\
\lim_{n\to\infty}(z_n w_n) &= z w,\\
\lim_{n\to\infty}\overline{z_n} &= \overline{z}.
\end{align}
Moreover, if $w_n\neq 0$ for all $n$ and $w\neq 0$, then $(z_n/w_n)_{n=1}^\infty$ is convergent and
\[
\label{eq:4.u278}
\lim_{n\to\infty}\frac{z_n}{w_n} = \frac{z}{w}.
\]
\end{lemma}

\begin{definition}
\label{def:4.22}
[Complex exponential]
For each $z\in\mathbb{C}$, the \emph{complex exponential} is defined by the power series
\[
\label{eq:4.u289}
\exp(z)=\sum_{n=0}^{\infty}\frac{z^n}{n!}.
\]
\end{definition}

\begin{proposition}
\label{prop:4.18}
For every $z\in\mathbb{C}$, one has
\[
\label{eq:4.u291}
\exp(\overline{z})=\overline{\exp(z)}.
\]
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:4.18}
Write $z=x+iy$ with $x,y\in\mathbb{R}$. Then $\overline{z}=x-iy$ and
\[
\label{eq:4.u292}
\exp(z)=e^{x+iy}=e^x(\cos y+i\sin y),\qquad
\exp(\overline{z})=e^{x-iy}=e^x(\cos y-i\sin y).
\]
Since complex conjugation fixes real numbers and satisfies $\overline{a+ib}=a-ib$ for $a,b\in\mathbb{R}$, one has
\[
\label{eq:4.u293}
\overline{\exp(z)}=\overline{e^x(\cos y+i\sin y)}=e^x(\cos y-i\sin y)=\exp(\overline{z}).
\]
\end{proof}

