\begin{proposition}
\label{prop:4.19}
For every complex number $z\in\mathbb{C}$,
\[
\label{eq:4.u294}
\Re(z)=\frac{z+\overline{z}}{2}\qquad\text{and}\qquad \Im(z)=\frac{z-\overline{z}}{2i}.
\]
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:4.19}
Let $z\in\mathbb{C}$. Write $z=x+iy$ with $x,y\in\mathbb{R}$. Then $\overline{z}=x-iy$, so
\[
\label{eq:4.u295}
\frac{z+\overline{z}}{2}=\frac{(x+iy)+(x-iy)}{2}=\frac{2x}{2}=x=\Re(z),
\]
and
\[
\label{eq:4.u296}
\frac{z-\overline{z}}{2i}=\frac{(x+iy)-(x-iy)}{2i}=\frac{2iy}{2i}=y=\Im(z).
\]
\end{proof}

