\begin{proposition}
\label{prop:4.20}
If $z,w\in\mathbb{C}$ and $w\neq 0$, then
\[
\label{eq:4.u297}
\left|\frac{z}{w}\right|=\frac{|z|}{|w|}.
\]
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:4.20}
Since $w\neq 0$, the quotient $z/w$ is defined and equals $z\cdot (1/w)$. Using multiplicativity of the complex modulus, $|ab|=|a|\,|b|$ for $a,b\in\mathbb{C}$, yields
\[
\label{eq:4.u298}
\left|\frac{z}{w}\right|=\left|z\cdot \frac{1}{w}\right|=|z|\,\left|\frac{1}{w}\right|.
\]
Also, $w\cdot (1/w)=1$, so applying multiplicativity again gives
\[
\label{eq:4.u299}
1=|1|=\left|w\cdot \frac{1}{w}\right|=|w|\,\left|\frac{1}{w}\right|.
\]
Because $w\neq 0$, one has $|w|>0$, hence $\left|\frac{1}{w}\right|=\frac{1}{|w|}$. Substituting into the first displayed equation gives
\[
\label{eq:4.u300}
\left|\frac{z}{w}\right|=|z|\cdot \frac{1}{|w|}=\frac{|z|}{|w|}.
\]
\end{proof}

