\begin{proposition}
\label{prop:4.22}
There does not exist a partition of $\mathbb{C}$ into three disjoint classes, called \emph{positive}, \emph{negative}, and \emph{zero}, such that the following axioms hold for all $z,w\in\mathbb{C}$:
\begin{enumerate}
\item \textbf{(Trichotomy)} Exactly one of the following holds: $z$ is positive, $z$ is negative, or $z=0$.
\item \textbf{(Negation)} If $z$ is positive then $-z$ is negative, and if $z$ is negative then $-z$ is positive.
\item \textbf{(Additivity)} If $z$ and $w$ are positive, then $z+w$ is positive.
\item \textbf{(Multiplicativity)} If $z$ and $w$ are positive, then $zw$ is positive.
\end{enumerate}
\end{proposition}

\begin{theorem}
\label{thm:4.14}
For all $z,w\in\mathbb{C}$,
\[
\label{eq:4.u307}
\exp(z+w)=\exp(z)\,\exp(w).
\]
\end{theorem}

\begin{definition}
\label{def:4.24}
[Trigonometric functions]
For $z\in\mathbb{C}$, define
\[
\label{eq:4.u312}
\cos(z) := \frac{e^{iz}+e^{-iz}}{2}
\]
and
\[
\label{eq:4.u313}
\sin(z) := \frac{e^{iz}-e^{-iz}}{2i}.
\]
\end{definition}

\begin{proposition}
\label{prop:4.23}
[Reality and absolute convergence on $\mathbb{R}$]
For every $x\in\mathbb{R}$, the series
\[
\label{eq:4.u315}
\sum_{n=0}^{\infty} \frac{(-1)^n x^{2n}}{(2n)!}\quad\text{and}\quad\sum_{n=0}^{\infty} \frac{(-1)^n x^{2n+1}}{(2n+1)!}
\]
converge absolutely. Consequently, if
\[
\label{eq:4.u316}
\cos(x):=\sum_{n=0}^{\infty} \frac{(-1)^n x^{2n}}{(2n)!},\qquad \sin(x):=\sum_{n=0}^{\infty} \frac{(-1)^n x^{2n+1}}{(2n+1)!},
\]
then $\cos(x),\sin(x)\in\mathbb{R}$ for all $x\in\mathbb{R}$.
\end{proposition}

\begin{theorem}\label{thm:4.7.2.b}
For every real number $x$, we have
\[
\sin'(x)=\cos(x),\qquad \cos'(x)=-\sin(x).
\]
\end{theorem}

\begin{theorem}\label{thm:4.7.2.c}
For every real number $x$, we have
\[
\sin(-x)=-\sin(x),\qquad \cos(-x)=\cos(x).
\]
\end{theorem}

\begin{theorem}\label{thm:4.7.2.e}
We have
\[
\sin(0)=0,\qquad \cos(0)=1.
\]
\end{theorem}

\begin{lemma}
\label{lem:4.9}
There exists a real number $x>0$ such that $\sin x=0$.
\end{lemma}

\begin{definition}
\label{def:4.26}
Define
\[
\label{eq:4.u331}
\pi := \inf\{x\in(0,\infty):\sin(x)=0\}.
\]
\end{definition}

\begin{proposition}
\label{prop:4.24}
Let $f:\mathbb{R}\to\mathbb{R}$ be differentiable at $x_0\in\mathbb{R}$. Assume that $f(x_0)=0$ and $f'(x_0)\neq 0$. Then there exists $c>0$ such that for every $y\in\mathbb{R}$ with $0<|y-x_0|<c$, one has $f(y)\neq 0$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:4.24}
Since $f$ is differentiable at $x_0$ and $f(x_0)=0$, for $y\neq x_0$ define
\[
\label{eq:4.u337}
q(y):=\frac{f(y)-f(x_0)}{y-x_0}=\frac{f(y)}{y-x_0}.
\]
Then $\lim_{y\to x_0} q(y)=f'(x_0)\neq 0$. Choose $\varepsilon:=\tfrac12|f'(x_0)|>0$. By the definition of limit, there exists $c>0$ such that whenever $0<|y-x_0|<c$,
\[
\label{eq:4.u338}
|q(y)-f'(x_0)|<\varepsilon.
\]
If $q(y)=0$ for some such $y$, then
\[
\label{eq:4.u339}
|f'(x_0)|=|f'(x_0)-q(y)|<\varepsilon=\tfrac12|f'(x_0)|,
\]
a contradiction. Hence $q(y)\neq 0$ for all $0<|y-x_0|<c$. Since $f(y)=(y-x_0)q(y)$ and $y-x_0\neq 0$ in this range, it follows that $f(y)\neq 0$.
\end{proof}

