\begin{proposition}
\label{prop:4.27}
Let $r,s>0$ and $\theta,\alpha\in\mathbb{R}$. If $re^{i\theta}=se^{i\alpha}$, then $r=s$ and there exists $k\in\mathbb{Z}$ such that $\theta=\alpha+2\pi k$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:4.27}
Assume $re^{i\theta}=se^{i\alpha}$. Taking moduli gives
\[
\label{eq:4.u345}
|re^{i\theta}|=|se^{i\alpha}|.
\]
Since $|e^{it}|=1$ for all $t\in\mathbb{R}$, it follows that $r=s$.

With $r=s>0$, divide the original equality by $r$ to obtain $e^{i\theta}=e^{i\alpha}$. Then
\[
\label{eq:4.u346}
e^{i(\theta-\alpha)}=1.
\]
Using Euler's formula, $e^{i(\theta-\alpha)}=\cos(\theta-\alpha)+i\sin(\theta-\alpha)$, so $\cos(\theta-\alpha)=1$ and $\sin(\theta-\alpha)=0$. Hence $\theta-\alpha=2\pi k$ for some $k\in\mathbb{Z}$, i.e. $\theta=\alpha+2\pi k$.
\end{proof}

