\begin{proposition}
\label{prop:4.29}
[de Moivre identities]
For every $\theta\in\mathbb{R}$ and every $n\in\mathbb{Z}$,
\[
\label{eq:4.u348}
\cos(n\theta)=\Re\bigl((\cos\theta+i\sin\theta)^n\bigr),\qquad \sin(n\theta)=\Im\bigl((\cos\theta+i\sin\theta)^n\bigr).
\]
Equivalently,
\[
\label{eq:4.u349}
(\cos\theta+i\sin\theta)^n=\cos(n\theta)+i\sin(n\theta).
\]
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:4.29}
Set $z=\cos\theta+i\sin\theta$. Then $|z|=1$, so $z\neq 0$ and $z^n$ is defined for all $n\in\mathbb{Z}$.

First assume $n\ge 0$. The statement is clear for $n=0$, since $z^0=1=\cos 0+i\sin 0$. For $n\ge 1$, use induction. Suppose $z^n=\cos(n\theta)+i\sin(n\theta)$. Then
\[
\label{eq:4.u350}
\begin{aligned}
z^{n+1}&=z^n z=(\cos(n\theta)+i\sin(n\theta))(\cos\theta+i\sin\theta)\\
&=\bigl(\cos(n\theta)\cos\theta-\sin(n\theta)\sin\theta\bigr)+i\bigl(\sin(n\theta)\cos\theta+\cos(n\theta)\sin\theta\bigr)\\
&=\cos((n+1)\theta)+i\sin((n+1)\theta),
\end{aligned}
\]
using the addition formulas for cosine and sine. Hence the identity holds for all $n\in\mathbb{N}$.

Now let $n<0$ and write $n=-m$ with $m\in\mathbb{N}$. Since $|z|=1$, one has $z^{-1}=\overline z=\cos\theta-i\sin\theta=\cos(-\theta)+i\sin(-\theta)$. Applying the already proved nonnegative case to $z^{-1}$ gives
\[
\label{eq:4.u351}
z^{-m}=(z^{-1})^m=\cos(m(-\theta))+i\sin(m(-\theta))=\cos(-m\theta)+i\sin(-m\theta)=\cos(n\theta)+i\sin(n\theta).
\]
Therefore $(\cos\theta+i\sin\theta)^n=\cos(n\theta)+i\sin(n\theta)$ for all $n\in\mathbb{Z}$. Taking real and imaginary parts yields the stated formulas.
\end{proof}

