\begin{definition}
\label{def:4.27}
The tangent function is the map $\tan:(-\pi/2,\pi/2)\to\mathbb{R}$ defined by
\[
\label{eq:4.u352}
\tan(x):=\frac{\sin x}{\cos x}.
\]
\end{definition}

\begin{proposition}
\label{prop:4.30}
Define $\tan:(-\pi/2,\pi/2)\to\mathbb{R}$ by $\tan(x)=\dfrac{\sin x}{\cos x}$. Then $\tan$ is differentiable on $(-\pi/2,\pi/2)$ and
\[
\label{eq:4.u353}
\frac{d}{dx}\tan(x)=1+\tan^2(x)\qquad (x\in(-\pi/2,\pi/2)).
\]
In particular, $\tan$ is strictly increasing on $(-\pi/2,\pi/2)$. Moreover,
\[
\label{eq:4.u354}
\lim_{x\to\pi/2^-}\tan(x)=+\infty,\qquad \lim_{x\to-\pi/2^+}\tan(x)=-\infty.
\]
Consequently, $\tan$ is a bijection from $(-\pi/2,\pi/2)$ onto $\mathbb{R}$.
\end{proposition}

\begin{proposition}
\label{prop:4.31}
Let $\tan^{-1}:\mathbb{R}\to(-\pi/2,\pi/2)$ denote the inverse function of $\tan:(-\pi/2,\pi/2)\to\mathbb{R}$. Then $\tan^{-1}$ is differentiable on $\mathbb{R}$ and
\[
\label{eq:4.u359}
\frac{d}{dx}\tan^{-1}(x)=\frac{1}{1+x^2}\qquad (x\in\mathbb{R}).
\]
\end{proposition}

\begin{proposition}
\label{prop:4.32}
For every real number $x$ with $|x|<1$, the arctangent function admits the power series expansion
\[
\label{eq:4.u365}
\arctan(x)=\sum_{n=0}^{\infty}\frac{(-1)^n x^{2n+1}}{2n+1}.
\]
\end{proposition}

\begin{proposition}
\label{prop:4.33}
The following series identity holds:
\[
\label{eq:4.u370}
\pi=4\sum_{n=0}^{\infty}\frac{(-1)^n}{2n+1}=4-\frac{4}{3}+\frac{4}{5}-\frac{4}{7}+\cdots.
\]
In particular,
\[
\label{eq:4.u371}
4-\frac{4}{3}<\pi<4.
\]
\end{proposition}

\begin{definition}
\label{def:4.28}
Define $f:\mathbb{R}\to\mathbb{R}$ by
\[
\label{eq:4.u376}
f(x):=\sum_{n=1}^{\infty}4^{-n}\cos(32^n\pi x).
\]
\end{definition}

\begin{proposition}
\label{prop:4.34}
Define, for each $x\in\mathbb{R}$,
\[
\label{eq:4.u377}
f(x)=\sum_{n=1}^{\infty}4^{-n}\cos\bigl(32^n\pi x\bigr).
\]
Then the series $\sum_{n=1}^{\infty}4^{-n}\cos(32^n\pi x)$ converges uniformly on $\mathbb{R}$. In particular, $f$ is continuous on $\mathbb{R}$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:4.34}
For each $n\ge 1$ define $u_n(x)=4^{-n}\cos(32^n\pi x)$ for $x\in\mathbb{R}$. Since $|\cos(32^n\pi x)|\le 1$ for all $x$, it follows that
\[
\label{eq:4.u378}
|u_n(x)|\le 4^{-n}\qquad \text{for all }x\in\mathbb{R}.
\]
The numerical series $\sum_{n=1}^\infty 4^{-n}$ converges. Therefore, by the Weierstrass M-test, the series $\sum_{n=1}^{\infty}u_n(x)$ converges uniformly on $\mathbb{R}$.

Each function $u_n$ is continuous on $\mathbb{R}$, being a scalar multiple of the cosine function composed with an affine map. A uniformly convergent series of continuous functions has a continuous sum; hence $f$ is continuous on $\mathbb{R}$.
\end{proof}

