\begin{proposition}
\label{prop:4.35}
Let $f:\mathbb{R}\to\mathbb{R}$ be defined by
\[
\label{eq:4.u379}
f(x)=\sum_{n=1}^{\infty}4^{-n}\cos\bigl(32^n\pi x\bigr).
\]
Then, for every $j\in\mathbb{Z}$ and every integer $m\ge 1$,
\[
\label{eq:4.u380}
\left|f\left(\frac{j+1}{32^m}\right)-f\left(\frac{j}{32^m}\right)\right|\ge 4^{-m}.
\]
\end{proposition}

\begin{proposition}
\label{prop:4.36}
Define
\[
\label{eq:4.u390}
f(x)=\sum_{n=1}^{\infty}4^{-n}\cos\bigl(32^n\pi x\bigr),\qquad x\in\mathbb{R}.
\]
Then $f$ is nowhere differentiable; that is, for every $x_0\in\mathbb{R}$, the function $f$ is not differentiable at $x_0$.
\end{proposition}
